# hermes-device-sync: plugs into the shared `hermes` launcher. Before Hermes opens: sync, ask about
# skill updates (if Hermes Skills Updater is installed), one Hermes at a time, bring in a newer
# conversation from another device. After it closes: sync. `sync-hermes` = sync now.
# Generated by setup.py; re-run setup to change.
HERMES_SYNC_SCRIPTS='__SCRIPTS__'
HERMES_SYNC_PYTHON='__PYTHON__'
sync-hermes() { "$HERMES_SYNC_PYTHON" "$HERMES_SYNC_SCRIPTS/sync.py"; }
hermes_hook_before_20_sync() {
  sync-hermes
  _u="${HERMES_HOME:-$HOME/.hermes}/scripts/hermes-skills-updater.py"
  [ -f "$_u" ] && "$HERMES_SYNC_PYTHON" "$_u" prompt
  # One Hermes at a time: if another device has Hermes open, ask (close it there / stop here).
  HERMES_SYNC_WRAPPER_PID=$$ "$HERMES_SYNC_PYTHON" "$HERMES_SYNC_SCRIPTS/presence.py" start
  if [ $? -eq 3 ]; then echo "OK - keep using Hermes on the other device."; HERMES_STOP=1; return; fi
  # a newer conversation on another device is imported (Hermes's Terminal, if installed, then opens it)
  "$HERMES_SYNC_PYTHON" "$HERMES_SYNC_SCRIPTS/handoff.py" pick >/dev/null 2>&1
}
hermes_hook_after_80_sync() {
  echo "Syncing..."
  "$HERMES_SYNC_PYTHON" "$HERMES_SYNC_SCRIPTS/presence.py" stop 2>/dev/null
  sync-hermes
}
